css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page { size: A4 portrait; margin: 0; }
html, body { width: 210mm !important; min-height: 297mm !important; margin: 0 !important; padding: 0 !important; }
.print-format { width: 210mm !important; min-height: 297mm !important; margin: 0 !important; padding: 0 !important; background: #fff !important; }

.cdq, .cdq * { box-sizing: border-box; }
.cdq {
  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  padding: 0;
  overflow: hidden;
  color: #202020;
  background: #fff;
  font-family: "TH Sarabun Document", "TH Sarabun New", sans-serif;
  font-size: 3.65mm;
  font-weight: 400;
  line-height: 1.08;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.cdq:not(:last-child) { page-break-after: always; }
.cdq strong, .cdq b { font-weight: 700; }
.cdq p, .cdq dl, .cdq dt, .cdq dd, .cdq table { margin: 0; padding: 0; }

/* Header - measured from the supplied PDF */
.cdq-logo { position: absolute; left: 7.15mm; top: 6.35mm; width: 35.48mm; height: 13.55mm; object-fit: contain; }
.cdq-company { position: absolute; top: 5.55mm; right: 7.20mm; width: 125mm; color: #3c3c3c; font-size: 3.10mm; line-height: 1.42; text-align: right; white-space: nowrap; }
.cdq-company-name { font-weight: 700; }
.cdq-title { position: absolute; top: 29.05mm; left: 0; width: 210mm; font-size: 5.50mm; font-weight: 700; line-height: 1.15; text-align: center; }
.cdq-number { position: absolute; left: 165.52mm; top: 40.81mm; width: 37.76mm; height: 8.81mm; border-radius: 3.60mm; background: #d2d2d2; color: #a11d21; font-size: 3.65mm; font-weight: 700; line-height: 8.81mm; text-align: center; white-space: nowrap; }
.cdq-number-label { margin-right: 4.10mm; color: #a31b24; }

/* Customer/document information */
.cdq-info { font-size: 3.65mm; position: absolute; left: 6.82mm; top: 52.11mm; width: 196.39mm; height: 42.22mm; overflow: hidden; border: 0.24mm solid #a31b24; border-radius: 2.45mm; }
.cdq-info-left { position: absolute; left: 0; top: 0; width: 109.60mm; height: 100%; border-right: 0.24mm solid #a31b24; }
.cdq-info-right { position: absolute; left: 109.60mm; top: 0; width: 86.79mm; height: 100%; }
.cdq-attention-label { position: absolute; left: 3.82mm; top: 1.65mm; padding: 0 0.72mm; border-radius: 1.10mm; background: #ffea00; font-weight: 700; line-height: 5.20mm; }
.cdq-attention-value { position: absolute; left: 15.35mm; top: 1.67mm; }
.cdq-customer-code { position: absolute; right: 2.05mm; top: 1.25mm; font-size: 2.95mm; }
.cdq-customer-name { position: absolute; left: 15.35mm; right: 2mm; top: 7.75mm; white-space: nowrap; overflow: hidden; }
.cdq-address-block { position: absolute; left: 15.20mm; right: 2.20mm; top: 13.30mm; bottom: 2.00mm; overflow: hidden; font-size: 3.55mm; line-height: 1.42; white-space: normal; }
.cdq-address-block br { content: ""; display: block; margin: 0; }












.cdq-check:before, .cdq-check:after { content: ""; position: absolute; left: 0.43mm; top: 1.42mm; width: 2.35mm; border-top: 0.22mm solid #222; }



.cdq-meta-label, .cdq-meta-value { position: absolute; }
.cdq-meta-label { left: 3.80mm; font-size: 3.75mm; font-weight: 700; }
.cdq-meta-value { left: 34.55mm; right: 1.8mm; font-size: 3.55mm; white-space: nowrap; overflow: hidden; }
.cdq-meta-date-label, .cdq-meta-date-value { top: 1.78mm; }
.cdq-meta-validity-label, .cdq-meta-validity-value { top: 9.90mm; }
.cdq-meta-delivery-label, .cdq-meta-delivery-value { top: 18.27mm; }
.cdq-meta-payment-label, .cdq-meta-payment-value { top: 27.15mm; }
.cdq-highlight { display: inline-block; padding: 0 0.50mm; border-radius: 1.10mm; background: #ffea00; }
.cdq-page { position: absolute; right: 3.55mm; bottom: 1.85mm; font-weight: 700; white-space: nowrap; }
.cdq-page-value { margin-left: 2.50mm; font-weight: 400; }

/* Introduction and items */
.cdq-intro { font-size: 3.75mm; position: absolute; left: 12.66mm; top: 98.20mm; font-weight: 700; white-space: nowrap; }
.cdq-items { position: absolute; left: 6.82mm; top: 106.85mm; width: 196.39mm; height: 79.76mm; overflow: hidden; border: 0.24mm solid #a83335; border-radius: 2.45mm 2.45mm 0 0; }
.cdq-head { position: absolute; left: 0; top: 0; width: 100%; height: 9.65mm; border-bottom: 0.24mm solid #a83335; background: #d2d2d2; }
.cdq-head-cell { font-size: 3.65mm; position: absolute; top: 0; height: 9.65mm; padding-top: 1.30mm; border-right: 0.24mm solid #a83335; font-weight: 700; text-align: center; }
.cdq-col-no { left: 0; width: 12.02mm; }
.cdq-col-description { left: 12.02mm; width: 97.58mm; }
.cdq-col-quantity { left: 109.60mm; width: 28.74mm; }
.cdq-col-rate { left: 138.34mm; width: 28.41mm; }
.cdq-col-amount { left: 166.75mm; width: 29.64mm; border-right: 0; }
.cdq-body { position: absolute; left: 0; top: 9.65mm; width: 100%; height: 70.11mm; overflow: hidden; }
.cdq-vline { position: absolute; top: 0; bottom: 0; z-index: 1; border-left: 0.24mm solid #a83335; }
.cdq-vline-1 { left: 12.02mm; } .cdq-vline-2 { left: 109.60mm; } .cdq-vline-3 { left: 138.34mm; } .cdq-vline-4 { left: 166.75mm; }
.cdq-item-table { position: relative; z-index: 2; width: 196.39mm; border-collapse: collapse; table-layout: fixed; font-size: 3.55mm; line-height: 1.10; }
.cdq-item-table col:nth-child(1) { width: 12.02mm; } .cdq-item-table col:nth-child(2) { width: 97.58mm; } .cdq-item-table col:nth-child(3) { width: 28.74mm; } .cdq-item-table col:nth-child(4) { width: 28.41mm; } .cdq-item-table col:nth-child(5) { width: 29.64mm; }
.cdq-item-table td { height: 7.20mm; padding: 2.95mm 0 0; border: 0; vertical-align: top; white-space: nowrap; overflow: hidden; }
.cdq-item-no { padding-left: 3mm !important; text-align: left; }
.cdq-item-description { padding-left: 2.50mm !important; padding-right: 1mm !important; }
.cdq-item-quantity { text-align: center; }
.cdq-item-rate, .cdq-item-amount { padding-right: 1.25mm !important; text-align: right; }

/* Summary */
.cdq-summary { position: absolute; left: 6.82mm; top: 186.61mm; width: 196.39mm; height: 101.43mm; overflow: hidden; border: 0.24mm solid #a83335; border-top: 0; border-radius: 0 0 2.45mm 2.45mm; font-size: 3.55mm; }
.cdq-remarks { position: absolute; left: 0; top: 0; width: 109.60mm; height: 100%; border-right: 0.24mm solid #a83335; }
.cdq-remarks-title { position: absolute; left: 3.05mm; top: 1.30mm; font-weight: 700; }
.cdq-remarks-body { position: absolute; left: 4.95mm; right: 2.30mm; top: 7.62mm; line-height: 1.62; }
.cdq-sales-contact { position: absolute; left: 4.95mm; right: 2.30mm; top: 38.20mm; line-height: 1.62; }
.cdq-totals { position: absolute; left: 109.60mm; top: 0; width: 86.79mm; height: 100%; }
.cdq-total-label, .cdq-total-value { position: absolute; }
.cdq-total-label { left: 3.90mm; } .cdq-total-value { right: 1.25mm; text-align: right; }
.cdq-total-sub-label, .cdq-total-sub-value { top: 1.65mm; }
.cdq-total-vat-label, .cdq-total-vat-value { top: 9.45mm; }
.cdq-total-grand-label, .cdq-total-grand-value { top: 17.25mm; font-weight: 700; }
.cdq-words { position: absolute; left: 0; top: 25.95mm; width: 100%; height: 8.81mm; padding: 1.55mm 1.25mm 0 2mm; border-top: 0.24mm solid #a83335; border-bottom: 0.24mm solid #a83335; background: #d2d2d2; font-weight: 700; text-align: right; white-space: nowrap; overflow: hidden; }
.cdq-bank { position: absolute; left: 0; top: 34.76mm; width: 100%; height: 24.13mm; border-bottom: 0.24mm solid #a83335; }
.cdq-bank-label, .cdq-bank-value { position: absolute; }
.cdq-bank-label { left: 5.15mm; font-weight: 700; } .cdq-bank-value { left: 29.55mm; }
.cdq-bank-row1-label, .cdq-bank-row1-value { top: 1.65mm; }
.cdq-bank-row2-label, .cdq-bank-row2-value { top: 9.35mm; }
.cdq-bank-row3-label, .cdq-bank-row3-value { top: 17.05mm; }
.cdq-bank-branch-label { position: absolute; left: 50.65mm; top: 9.35mm; font-weight: 700; }
.cdq-bank-branch-value { position: absolute; left: 67.20mm; top: 9.35mm; white-space: nowrap; }
.cdq-sign { position: absolute; left: 0; top: 58.89mm; width: 100%; height: 42.54mm; text-align: center; }
.cdq-respect { position: absolute; left: 0; top: 2.55mm; width: 100%; }
.cdq-sign-line { position: absolute; left: 7.05mm; right: 7.85mm; top: 20.05mm; border-bottom: 0.18mm dotted #555; }
.cdq-sign-name { position: absolute; left: 0; top: 26.40mm; width: 100%; }
.cdq-sign-role { position: absolute; left: 0; top: 33.25mm; width: 100%; }

/* Bilingual labels retain the measured layout by using compact type only. */
.cdq-copy-label { font-size: 3.20mm; font-weight: 400; }
.cdq-bilingual .cdq-company { font-size: 2.45mm; }
.cdq-bilingual .cdq-title { font-size: 5.00mm; }
.cdq-bilingual .cdq-attention-label { font-size: 3.00mm; }
.cdq-bilingual .cdq-attention-value { left: 23mm; }
.cdq-bilingual .cdq-meta-label { left: 2.20mm; font-size: 2.65mm; }
.cdq-bilingual .cdq-meta-value { left: 38mm; font-size: 3.10mm; }
.cdq-bilingual .cdq-intro { font-size: 3.15mm; }
.cdq-bilingual .cdq-head-cell { font-size: 3.00mm; }
.cdq-bilingual .cdq-total-label { font-size: 2.90mm; }
.cdq-bilingual .cdq-bank { font-size: 3.00mm; }
.cdq-bilingual .cdq-bank-value { left: 33mm; }
